  aU = `%1$s fichas`,
  oU = `Não foi possível abrir o envelope`,
  sU = `A GRANDE CORRIDA DO IMPERADOR`,
  cU = `A Origem do Horóscopo Chinês`,
  lU = `A GRANDE CORRIDA | 1º DIA`,
  uU = `A GRANDE CORRIDA | 2º DIA`,
  dU = `A GRANDE CORRIDA | 3º DIA`,
  fU = `A GRANDE CORRIDA | 4º DIA`,
  pU = `A Rata astuta foi a primeira a chegar ao campo celestial. Já que ela não gosta de nadar, pegou uma carona confiável no lombo do Boi e saltou entusiasmadamente para o jardim paradisíaco do Imperador antes que a sua carona chegasse à margem.

O Boi constante atravessou o rio com facilidade, sem se preocupar com os resultados da corrida. O segundo lugar é bom para ele, que ficou feliz com o sucesso da Rata.`,
  mU = `O Tigre autossuficiente foi cauteloso demais para ultrapassar o Boi e achou melhor ficar em terceiro lugar do que em lugar nenhum.

O Coelho veloz acabou saltando sobre um pedaço de madeira, flutuando rapidamente sem destino. Mas valeu-se da sorte na falta da estratégia quando um vento prestativo acelerou a sua jornada na direção certa. 

O ponto de vista privilegiado do Dragão voador revelou alguns necessitados de ajuda, e ele parou sempre que possível, inclusive para presentear um sopro de vento para o Coelho atravessar o rio. A honra importa muito mais do que a vitória, e o quinto lugar satisfez para o Dragão.`,
  hU = `A Cobra sorrateira não estava lá muito interessada no esforço à longa distância, então enroscou-se despercebida no casco do Cavalo. 

Enquanto o Cavalo galopava em direção à linha de chegada, a Cobra desenroscou-se e espantou a sua carona por tempo suficiente para esgueirar-se até o sexto lugar, enquanto o Cavalo errante seguiu trotando na sua cola.`,
  gU = `A Cabra, o Macaco e o Galo trabalharam em equipe, mas deixaram a Cabra ficar com o oitavo lugar, já que ela havia feito o maior esforço durante a viagem. O Macaco animado chegou em nono, e o Galo pomposo desfilou em décimo, orgulhoso de tão justa que fora a ordem.

O Cachorro galhofeiro estava mais interessado em brincar na água e concluiu que o décimo-primeiro lugar seria uma boa troca por toda aquela diversão.

Em décimo-segundo, chegou o Porco, que parara para comer e cochilar, pois sabiamente já estava ciente de que todos os animais teriam a sua vez ao lado do Imperador.`,
  _U = `As alterações ao perfil serão aplicadas após análise`,
