  Bpe = `Apenas os dados coletados no limite de quadros padrão do %1$s (%2$s QPS) são contabilizados. Momentos de ociosidade e amostras inválidas são removidas. Várias amostras são coletadas de cada sessão.`,
  Vpe = `Lacunas no gráfico (ex.: entre %1$s e %2$s QPS) podem ser causadas pela sincronização vertical (VSync), que sincroniza a entrega dos quadros com a taxa de atualização da tela para evitar rasgos na imagem. Isso pode fazer com que as amostras se concentrem em %1$s e %2$s QPS, mesmo quando a taxa de quadros média do jogo estiver entre esses valores. Esse comportamento é esperado ao usar a sincronização vertical e, embora possa afetar o ritmo dos quadros, não necessariamente causa engasgos perceptíveis.`,
